      const ny = (b.y - k.y) / Math.max(0.001, bd);
      b.x = k.x + nx * 0.95;
      b.y = k.y + ny * 0.95;
      b.vy = Math.abs(b.vy) * 0.38 + 4.4;
      b.vx += nx * 3.4 + rand(-2.6, 2.6);
      k.saveCd = 1.15;
      game.stats.saves++;
      game.shake = Math.max(game.shake, 0.25);
