  // ── Entity rendering ─────────────────────────────────────────
  function drawGroundShadow(px, py, rx, ry, alpha = 0.34) {
    ctx.save();
    const g = ctx.createRadialGradient(px + rx * 0.15, py, 0, px + rx * 0.15, py, Math.max(rx, ry));
    g.addColorStop(0, `rgba(0, 8, 13, ${alpha})`);
    g.addColorStop(0.62, `rgba(0, 8, 13, ${alpha * 0.52})`);
    g.addColorStop(1, 'rgba(0, 8, 13, 0)');
    ctx.fillStyle = g;
    ellipsePath(ctx, px + rx * 0.15, py, rx, ry);
    ctx.fill();
    ctx.restore();
  }

  function drawBall() {
    const b = game.ball;
    const s = view.s;
    const px = sx(b.x);
    const py = sy(b.y);
    const r = b.radius * s;
    const speed = hypot(b.vx, b.vy);

    drawGroundShadow(px + r * 0.5, py + r * 0.62, r * 1.16, r * 0.76, 0.42);

    if (speed > 6) {
      ctx.save();
      for (const t of game.trail) {
        const a = clamp(t.life / t.maxLife, 0, 1) * 0.13;
        ctx.fillStyle = `rgba(230, 250, 255, ${a})`;
        ctx.beginPath();
        ctx.arc(sx(t.x), sy(t.y), r * (0.5 + a * 1.5), 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }

    const g = ctx.createRadialGradient(px - r * 0.36, py - r * 0.46, r * 0.08, px, py, r * 1.08);
    g.addColorStop(0, '#ffffff');
    g.addColorStop(0.4, '#f4fbfc');
    g.addColorStop(0.78, '#c7d7da');
    g.addColorStop(1, '#7f939a');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(px, py, r, 0, TAU);
    ctx.fill();

    // Pentagon patches.
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(b.rot);
    ctx.fillStyle = 'rgba(16, 34, 42, 0.78)';
    const centerPatch = r * 0.26;
    ctx.beginPath();
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU - Math.PI / 2;
      const x = Math.cos(a) * centerPatch;
      const y = Math.sin(a) * centerPatch;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU - Math.PI / 2;
      const cx = Math.cos(a) * r * 0.64;
      const cy = Math.sin(a) * r * 0.64;
      const pr = r * 0.18;
      ctx.beginPath();
      for (let j = 0; j < 5; j++) {
