    ctx.restore();

    ctx.strokeStyle = 'rgba(9, 27, 36, 0.28)';
    ctx.lineWidth = Math.max(0.6, s * 0.026);
    ctx.beginPath();
    ctx.arc(px, py, r, 0, TAU);
